<?php
use PHPUnit\Framework\TestCase;
use Typecho\Common;
use Utils\PasswordHash;

/**
 * Common::hashPassword() / hashValidate() / passwordNeedsRehash(), with hashValidate()'s fallback chain
 * password_verify() -> phpass $P$ -> Typecho $T$ -> bare md5. Utils\PasswordHash is the frozen legacy
 * phpass implementation and must behave exactly as before.
 * Legacy fixtures are hard-coded on purpose: they must keep validating without regenerating them.
 */
final class PasswordHashTest extends TestCase
{
    private const PASSWORD = 's3cret-密码';

    /** generated by the original phpass 0.2 PasswordHash(8, true)->hashPassword() */
    private const PHPASS_HASH = '$P$B2EpzX6laLl8psZuLXUfD3uk6XUwro/';
    private const PHPASS_ADMIN_HASH = '$P$BZu8OfbVk9JhNynyGaUx8t8L8I128U1';

    /** Common::hash('legacy-pass', 'abcdefghi') */
    private const TYPECHO_HASH = '$T$abcdefghiefc6995da060f7fa205aef12e4620260';

    /** md5('admin') */
    private const MD5_HASH = '21232f297a57a5a743894a0e4a801fc3';

    public function testPasswordHashRoundTrip(): void
    {
        $hash = Common::hashPassword(self::PASSWORD);

        $this->assertStringStartsNotWith('$P$', $hash);
        $this->assertNotSame($hash, Common::hashPassword(self::PASSWORD), 'salt must be random');
        $this->assertTrue(password_verify(self::PASSWORD, $hash));
        $this->assertFalse(Common::passwordNeedsRehash($hash));
        $this->assertLessThanOrEqual(64, strlen($hash), 'must fit typecho_users.password varchar(64)');
        $this->assertTrue(Common::hashValidate(self::PASSWORD, $hash));
        $this->assertFalse(Common::hashValidate(self::PASSWORD . ' ', $hash));
    }

    public function testBcryptHashValidates(): void
    {
        $this->assertTrue(Common::hashValidate(self::PASSWORD, password_hash(self::PASSWORD, PASSWORD_BCRYPT)));
    }

    public function testPhpassHashStillValidates(): void
    {
        // the built-in functions do not understand $P$, which is why phpass is kept
        $this->assertFalse(password_verify(self::PASSWORD, self::PHPASS_HASH));

        $this->assertTrue(Common::hashValidate(self::PASSWORD, self::PHPASS_HASH));
        $this->assertTrue(Common::hashValidate('admin', self::PHPASS_ADMIN_HASH));
        $this->assertFalse(Common::hashValidate('admin', self::PHPASS_HASH));
    }

    public function testLegacyPhpassClassIsUnchanged(): void
    {
        $hasher = new PasswordHash(8, true);
        $hash = $hasher->hashPassword(self::PASSWORD);

        $this->assertStringStartsWith('$P$', $hash);
        $this->assertSame(34, strlen($hash));
        $this->assertTrue($hasher->checkPassword(self::PASSWORD, $hash));
        $this->assertFalse($hasher->checkPassword('wrong', $hash));
        $this->assertTrue($hasher->checkPassword(self::PASSWORD, self::PHPASS_HASH));

        // phpass never accepted bare md5
        $this->assertFalse($hasher->checkPassword('admin', self::MD5_HASH));

        // hashes still produced by plugins through phpass validate in the core and get upgraded on login
        $this->assertTrue(Common::hashValidate(self::PASSWORD, $hash));
        $this->assertTrue(Common::passwordNeedsRehash($hash));
    }

    /**
     * Plugins written for phpass use the global PasswordHash alias and phpass' original
     * CamelCase method names; the alias constant is defined per process, hence the isolation.
     *
     * @runInSeparateProcess
     * @preserveGlobalState disabled
     */
    public function testLegacyPluginCallsDoNotFatal(): void
    {
        define('__TYPECHO_CLASS_ALIASES__', ['PasswordHash' => '\\Utils\\PasswordHash']);

        $hasher = new \PasswordHash(8, true);
        $hash = $hasher->HashPassword('plugin-pass');

        $this->assertInstanceOf(PasswordHash::class, $hasher);
        $this->assertStringStartsWith('$P$', $hash);
        $this->assertTrue($hasher->CheckPassword('plugin-pass', $hash));
        $this->assertTrue(Common::hashValidate('plugin-pass', $hash));
    }

    public function malformedPhpassProvider(): array
    {
        return [
            'prefix only'      => ['$P$'],
            'truncated'        => [substr(self::PHPASS_HASH, 0, 20)],
            'short salt'       => ['$P$B2Epz'],
            'too long'         => [self::PHPASS_HASH . 'x'],
            'invalid char'     => ['$P$B2EpzX6laLl8psZuLXUfD3uk6XUwro#'],
            'invalid cost'     => ['$P$#2EpzX6laLl8psZuLXUfD3uk6XUwro/'],
            // valid charset and length, but a cost phpass refuses and would hand to crypt()
            'cost below 2^7'   => ['$P$22EpzX6laLl8psZuLXUfD3uk6XUwro/'],
            'cost above 2^30'  => ['$P$T2EpzX6laLl8psZuLXUfD3uk6XUwro/'],
            'tampered digest'  => [substr(self::PHPASS_HASH, 0, -1) . '0'],
        ];
    }

    /**
     * Must return false without any notice / deprecation: in particular PHP 7.4's
     * "crypt(): Supplied salt is not valid for DES" when phpass falls back to crypt().
     *
     * @dataProvider malformedPhpassProvider
     */
    public function testMalformedPhpassHashIsRejectedSilently(string $hash): void
    {
        $errors = [];
        set_error_handler(function (int $errno, string $errstr) use (&$errors): bool {
            $errors[] = $errstr;
            return true;
        });

        try {
            $result = Common::hashValidate(self::PASSWORD, $hash);
        } finally {
            restore_error_handler();
        }

        $this->assertFalse($result);
        $this->assertSame([], $errors);
    }

    public function testTypechoHashStillValidates(): void
    {
        $this->assertTrue(Common::hashValidate('legacy-pass', self::TYPECHO_HASH));
    }

    public function testBareMd5StillValidates(): void
    {
        $this->assertTrue(Common::hashValidate('admin', self::MD5_HASH));
    }

    public function testPasswordNeedsRehash(): void
    {
        $this->assertTrue(Common::passwordNeedsRehash(self::PHPASS_HASH));
        $this->assertTrue(Common::passwordNeedsRehash(self::TYPECHO_HASH));
        $this->assertTrue(Common::passwordNeedsRehash(self::MD5_HASH));
        $this->assertFalse(Common::passwordNeedsRehash(Common::hashPassword(self::PASSWORD)));
    }

    /**
     * Core generation and rehash points must go through Common, never password_*() or phpass directly.
     */
    public function testCoreGenerationPointsUseCommonHashPassword(): void
    {
        $files = [
            'var/Widget/Register.php'      => 1,
            'var/Widget/Users/Edit.php'    => 2,
            'var/Widget/Users/Profile.php' => 1,
            'install.php'                  => 1,
            'var/Widget/User.php'          => 1, // rehash on login
        ];

        foreach ($files as $file => $count) {
            $source = file_get_contents(__TYPECHO_ROOT_DIR__ . '/' . $file);
            $this->assertSame($count, substr_count($source, 'Common::hashPassword('), $file);
            $this->assertStringNotContainsString('password_hash(', $source, $file);
            $this->assertStringNotContainsString('password_needs_rehash', $source, $file);
            $this->assertStringNotContainsString('PASSWORD_DEFAULT', $source, $file);
            $this->assertStringNotContainsString('PasswordHash', $source, $file);
        }
    }

    public function wrongPasswordProvider(): array
    {
        return [
            'password_hash' => [password_hash('right', PASSWORD_DEFAULT)],
            'phpass'        => [self::PHPASS_HASH],
            'typecho'       => [self::TYPECHO_HASH],
            'md5'           => [self::MD5_HASH],
        ];
    }

    /**
     * @dataProvider wrongPasswordProvider
     */
    public function testWrongPasswordIsRejected(string $hash): void
    {
        foreach (['wrong', '', 'Admin', self::PASSWORD . 'x'] as $password) {
            $this->assertFalse(Common::hashValidate($password, $hash), $password);
        }
    }

    public function testMissingOrEmptyHashIsRejected(): void
    {
        $this->assertFalse(Common::hashValidate(null, self::MD5_HASH));
        $this->assertFalse(Common::hashValidate('admin', null));
        $this->assertFalse(Common::hashValidate('', ''));
        $this->assertFalse(Common::hashValidate('admin', ''));
        $this->assertFalse(Common::hashValidate('admin', '*0'));
    }
}
